        long v3x = x[3] - x[1];
        long v3y = y[3] - y[1];

        if (v2x * v3x + v2y * v3y <= 0) ok = false;

        if (dist2(x[1], y[1], x[2], y[2]) != dist2(x[1], y[1], x[3], y[3])) ok = false;

        long dx = x[3] - x[2];
        long dy = y[3] - y[2];

        if (cross(dx, dy, x[4] - x[2], y[4] - y[2]) != 0) ok = false;
