        if ((x[6] - x[4]) * dx + (y[6] - y[4]) * dy != 0) ok = false;
        if ((x[7] - x[5]) * dx + (y[7] - y[5]) * dy != 0) ok = false;

        if (dist2(x[4], y[4], x[6], y[6]) != dist2(x[5], y[5], x[7], y[7])) ok = false;

        long c1 = cross(dx, dy, x[1] - x[2], y[1] - y[2]);
        long c6 = cross(dx, dy, x[6] - x[2], y[6] - y[2]);

        if (!((c1 < 0 && c6 > 0) || (c1 > 0 && c6 < 0))) ok = false;

        System.out.println(ok ? "S" : "N");
    }
}
